1	// repo-engine: Record write/read operations for ATProto repositories.
2	//
3	// Provides put_record, get_record, and delete_record functions that wrap
4	// atrium-repo's Repository methods with the CommitSigner pattern.
5	
6	use std::collections::BTreeMap;
7	use std::time::{SystemTime, UNIX_EPOCH};
8	
9	use atrium_api::types::string::Tid;
10	use atrium_repo::repo::Repository;
11	use atrium_repo::Cid;
12	use base64::Engine;
13	use ipld_core::ipld::Ipld;
14	use serde::{de::DeserializeOwned, Serialize};
15	
16	use crate::signer::CommitSigner;
17	
18	/// Base32-sortable alphabet for TID encoding.
19	///
20	/// Maintains lexicographic sort order when encoded TIDs are compared as strings,
21	/// ensuring timestamp ordering is preserved.
22	const BASE32_SORTABLE: &[u8; 32] = b"REDACTED";
23	
24	/// Generate a Timestamp Identifier (TID) for ATProto record keys.
25	///
26	/// A TID is a 64-bit integer encoded as a 13-character base32-sortable string:
27	/// - Bit 0 (MSB): Always 0
28	/// - Bits 1-53: Microseconds since UNIX epoch
29	/// - Bits 54-63: Random 10-bit clock identifier
30	///
31	/// The random clock identifier provides collision resistance when multiple workers
32	/// generate TIDs in the same microsecond.
33	pub fn generate_tid() -> String {
34	    encode_tid(now_tid_int())
35	}
36	
37	/// The current time as a TID integer: microseconds since the UNIX epoch in the high bits, a
38	/// random 10-bit clock identifier in the low bits (collision resistance across workers).
39	fn now_tid_int() -> u64 {
40	    use rand_core::{OsRng, RngCore};
41	    let micros = SystemTime::now()
42	        .duration_since(UNIX_EPOCH)
43	        .expect("system clock before UNIX epoch")
44	        .as_micros() as u64;
45	    let clock_id: u64 = (OsRng.next_u32() & 0x3FF) as u64;
46	    // 0 | micros (53 bits) | clock_id (10 bits).
47	    (micros << 10) | clock_id
48	}
49	
50	/// Encode a TID integer as a 13-character base32-sortable string (big-endian).
51	fn encode_tid(mut v: u64) -> String {
52	    let mut chars = [0u8; 13];
53	    for i in (0..13).rev() {
54	        chars[i] = BASE32_SORTABLE[(v & 0x1F) as usize];
55	        v >>= 5;
56	    }
57	    String::from_utf8(chars.to_vec()).expect("base32 encoding is always valid ASCII")
58	}
59	
60	/// Decode a 13-character base32-sortable TID string back to its integer value. An unknown
61	/// character decodes as 0, so a malformed input only weakens the monotonicity bump below —
62	/// it never panics.
63	fn decode_tid(tid: &str) -> u64 {
64	    let mut v = 0u64;
65	    for b in tid.bytes() {
66	        let idx = BASE32_SORTABLE.iter().position(|&c| c == b).unwrap_or(0) as u64;
67	        v = (v << 5) | idx;
68	    }
69	    v
70	}
71	
72	/// Compute the `rev` for a new commit: a fresh time-ordered TID guaranteed to be strictly
73	/// greater than the previous commit's `rev`.
74	///
75	/// ATProto requires a repo's commit `rev`s to increase strictly — a relay drops any commit
76	/// whose `rev` is ≤ the last one it saw as stale, silently desyncing the repo from the
77	/// network. atrium's `CommitBuilder` derives `rev` purely from the wall clock with a zero
78	/// clock id (`Tid::now(0)`), so two commits in the same microsecond collide and a backward
79	/// clock step (NTP correction, VM migration) yields a *decreasing* `rev`. Bumping to
80	/// `prev + 1` whenever the clock hasn't advanced past `prev` mirrors the reference PDS's
81	/// monotonic-timestamp guard.
82	fn next_commit_rev(prev_rev: &str) -> Result<Tid, RecordError> {
83	    let next = now_tid_int().max(decode_tid(prev_rev).saturating_add(1));
84	    Tid::new(encode_tid(next))
85	        .map_err(|e| RecordError::Repo(format!("construct monotonic commit rev: {e}")))
86	}
87	
88	/// Errors from record operations.
89	#[derive(Debug, thiserror::Error)]
90	pub enum RecordError {
91	    #[error("repository error: {0}")]
92	    Repo(String),
93	    #[error("record not found")]
94	    NotFound,
95	    #[error("invalid record path: {0}")]
96	    InvalidPath(String),
97	    #[error("invalid record: {0}")]
98	    InvalidRecord(String),
99	    #[error("record already exists: {0}")]
100	    AlreadyExists(String),
101	}
102	
103	/// A single mutation in an [`apply_writes`] batch.
104	///
105	/// `key` is the MST key (`<collection>/<rkey>`) and must already be validated via
106	/// [`validate_record_path`]; this layer trusts it and does not re-check the format.
107	pub enum WriteOp {
108	    /// Create a record, failing with [`RecordError::AlreadyExists`] if `key` is present.
109	    Create {
110	        key: String,
111	        value: serde_json::Value,
112	    },
113	    /// Create or update a record (upsert semantics, matching `putRecord`).
114	    Update {
115	        key: String,
116	        value: serde_json::Value,
117	    },
118	    /// Delete a record; a no-op (no commit) if `key` is absent, matching `deleteRecord`.
119	    Delete { key: String },
120	}
121	
122	/// The outcome of one applied [`WriteOp`], returned by [`apply_writes`] in batch order.
123	#[derive(Debug)]
124	pub struct WriteOutcome {
125	    /// The MST key that was written (`<collection>/<rkey>`).
126	    pub key: String,
127	    /// The new record block CID for create/update; `None` for delete.
128	    pub cid: Option<Cid>,
129	    /// The record's CID *before* this op ran — the ATProto `#repoOp.prev` (previous record CID)
130	    /// for an update or delete. `None` for a create (the key was absent) or for a delete of an
131	    /// already-absent key (the no-op path). Captured from the in-memory MST just before the op
132	    /// mutates it, so within-batch chaining is honoured: a create-then-update of the same key
133	    /// reports the just-created CID as the update's `prev`.
134	    pub prev: Option<Cid>,
135	}
136	
137	/// Apply a batch of record writes to `repo`, signing one commit per mutating write.
138	///
139	/// Writes are applied in order against the in-memory repo, so a later write observes the
140	/// effects of earlier ones. The repo root advances with each write; the **caller** then
141	/// performs a single optimistic-concurrency swap of the persisted root to `repo.root()`.
142	/// That makes the batch atomic: on any error this returns before the caller swaps, so the
143	/// persisted root is unchanged and nothing in the batch is observable. The intermediate
144	/// commits become orphaned blocks reclaimed by GC — the repo durably advances to a single
145	/// new head commit whose MST reflects every write.
146	///
147	/// Per-op semantics mirror the standalone record routes: `Create` fails if the key already
148	/// exists, `Update` upserts, and `Delete` is idempotent.
149	pub async fn apply_writes<S>(
150	    repo: &mut Repository<S>,
151	    signer: &CommitSigner,
152	    writes: &[WriteOp],
153	) -> Result<Vec<WriteOutcome>, RecordError>
154	where
155	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
156	{
157	    let mut outcomes = Vec::with_capacity(writes.len());
158	    for op in writes {
159	        let outcome = match op {
160	            WriteOp::Create { key, value } => {
161	                // Probe existence with a pure MST lookup (no record decode), matching the
162	                // Update/Delete arms below.
163	                if get_record_cid(repo, key).await?.is_some() {
164	                    return Err(RecordError::AlreadyExists(key.clone()));
165	                }
166	                let cid = put_record_json(repo, signer, key, value).await?;
167	                WriteOutcome {
168	                    key: key.clone(),
169	                    cid: Some(cid),
170	                    prev: None,
171	                }
172	            }
173	            WriteOp::Update { key, value } => {
174	                // The record being replaced, read before the write, is this op's `prev`.
175	                let prev = get_record_cid(repo, key).await?;
176	                let cid = put_record_json(repo, signer, key, value).await?;
177	                WriteOutcome {
178	                    key: key.clone(),
179	                    cid: Some(cid),
180	                    prev,
181	                }
182	            }
183	            WriteOp::Delete { key } => {
184	                // Idempotent: only commit a delete when the record is actually present. The
185	                // record being removed, read before the delete, is this op's `prev` (`None` on
186	                // the no-op path where the key was already absent).
187	                let prev = get_record_cid(repo, key).await?;
188	                if prev.is_some() {
189	                    delete_record(repo, signer, key).await?;
190	                }
191	                WriteOutcome {
192	                    key: key.clone(),
193	                    cid: None,
194	                    prev,
195	                }
196	            }
197	        };
198	        outcomes.push(outcome);
199	    }
200	    Ok(outcomes)
201	}
202	
203	/// Convert an incoming JSON record into the ATProto data model (DAG-CBOR-ready):
204	/// `{"$link": "<cid>"}` becomes a CID link, `{"$bytes": "<base64>"}` becomes a byte
205	/// string, and floats are rejected (the ATProto data model permits only integers).
206	///
207	/// Storing the raw JSON instead would encode CID links as plain maps, producing record
208	/// CIDs that no other ATProto implementation agrees with (and broken blob references).
209	pub fn json_to_record_value(json: &serde_json::Value) -> Result<Ipld, RecordError> {
210	    use serde_json::Value;
211	    match json {
212	        Value::Null => Ok(Ipld::Null),
213	        Value::Bool(b) => Ok(Ipld::Bool(*b)),
214	        Value::Number(n) => {
215	            if let Some(i) = n.as_i64() {
216	                Ok(Ipld::Integer(i128::from(i)))
217	            } else if let Some(u) = n.as_u64() {
218	                Ok(Ipld::Integer(i128::from(u)))
219	            } else {
220	                Err(RecordError::InvalidRecord(
221	                    "floats are not allowed in ATProto records".into(),
222	                ))
223	            }
224	        }
225	        Value::String(s) => Ok(Ipld::String(s.clone())),
226	        Value::Array(items) => Ok(Ipld::List(
227	            items
228	                .iter()
229	                .map(json_to_record_value)
230	                .collect::<Result<_, _>>()?,
231	        )),
232	        Value::Object(map) => {
233	            if map.len() == 1 {
234	                if let Some(Value::String(cid)) = map.get("$link") {
235	                    let cid = Cid::try_from(cid.as_str()).map_err(|e| {
236	                        RecordError::InvalidRecord(format!("invalid $link CID: {e}"))
237	                    })?;
238	                    return Ok(Ipld::Link(cid));
239	                }
240	                if let Some(Value::String(b64)) = map.get("$bytes") {
241	                    let bytes = base64::engine::general_purpose::STANDARD
242	                        .decode(b64)
243	                        .map_err(|e| {
244	                            RecordError::InvalidRecord(format!("invalid $bytes base64: {e}"))
245	                        })?;
246	                    return Ok(Ipld::Bytes(bytes));
247	                }
248	            }
249	            let mut out = BTreeMap::new();
250	            for (k, v) in map {
251	                out.insert(k.clone(), json_to_record_value(v)?);
252	            }
253	            Ok(Ipld::Map(out))
254	        }
255	    }
256	}
257	
258	/// Convert a stored record (ATProto data model) back to JSON for API responses:
259	/// CID links become `{"$link": "<cid>"}` and byte strings become `{"$bytes": "<base64>"}`.
260	///
261	/// Errors with [`RecordError::InvalidRecord`] if the record holds an `Ipld::Integer` outside
262	/// the JSON-representable range (fits neither `i64` nor `u64`). Local writes can't produce such
263	/// a value — `json_to_record_value` only accepts `i64`/`u64` — but a record imported via CAR
264	/// carries whatever the DAG-CBOR bytes encode. Surfacing the error keeps a malformed import from
265	/// reading back as a silently-substituted `null` (lossy data mutation).
266	pub fn record_value_to_json(ipld: &Ipld) -> Result<serde_json::Value, RecordError> {
267	    use serde_json::Value;
268	    Ok(match ipld {
269	        Ipld::Null => Value::Null,
270	        Ipld::Bool(b) => Value::Bool(*b),
271	        Ipld::Integer(i) => {
272	            let n = i64::try_from(*i)
273	                .map(serde_json::Number::from)
274	                .or_else(|_| u64::try_from(*i).map(serde_json::Number::from))
275	                .map_err(|_| {
276	                    RecordError::InvalidRecord(format!(
277	                        "integer {i} is outside the JSON-representable range (i64/u64)"
278	                    ))
279	                })?;
280	            Value::Number(n)
281	        }
282	        Ipld::Float(f) => serde_json::Number::from_f64(*f).map_or(Value::Null, Value::Number),
283	        Ipld::String(s) => Value::String(s.clone()),
284	        Ipld::Bytes(b) => {
285	            serde_json::json!({ "$bytes": base64::engine::general_purpose::STANDARD.encode(b) })
286	        }
287	        Ipld::List(items) => Value::Array(
288	            items
289	                .iter()
290	                .map(record_value_to_json)
291	                .collect::<Result<_, _>>()?,
292	        ),
293	        Ipld::Map(map) => Value::Object(
294	            map.iter()
295	                .map(|(k, v)| record_value_to_json(v).map(|jv| (k.clone(), jv)))
296	                .collect::<Result<_, _>>()?,
297	        ),
298	        Ipld::Link(cid) => serde_json::json!({ "$link": cid.to_string() }),
299	    })
300	}
301	
302	/// Collect the blob-reference CIDs contained in a single decoded record value.
303	///
304	/// An ATProto blob reference is a map `{"$type": "blob", "ref": <link>, ...}` whose `ref` is a
305	/// CID link — canonically an [`Ipld::Link`] (the form produced when a record is stored via
306	/// [`json_to_record_value`]), with a `{"$link": <link>}` map handled as a defensive fallback.
307	/// The walk recurses into every nested map and list, so a blob embedded deep inside a record
308	/// (e.g. `embed.images[].image`) is found. A CID may appear more than once if the same blob is
309	/// referenced repeatedly; the caller deduplicates.
310	///
311	/// Used by `com.atproto.repo.listMissingBlobs` (the referenced-vs-uploaded diff) and
312	/// `com.atproto.server.checkAccountStatus` (the expected-blob count) to derive a repo's blob
313	/// references without re-encoding records.
314	pub fn record_blob_cids(record: &Ipld) -> Vec<Cid> {
315	    let mut out = Vec::new();
316	    collect_blob_cids(record, &mut out);
317	    out
318	}
319	
320	fn collect_blob_cids(ipld: &Ipld, out: &mut Vec<Cid>) {
321	    match ipld {
322	        Ipld::Map(map) => {
323	            if let Some(Ipld::String(typ)) = map.get("$type") {
324	                if typ == "blob" {
325	                    match map.get("ref") {
326	                        // Canonical: `json_to_record_value` converts `{"$link": "..."}` to a link.
327	                        Some(Ipld::Link(cid)) => out.push(*cid),
328	                        // Fallback: `ref` is still a map with a `$link` link.
329	                        Some(Ipld::Map(ref_map)) => {
330	                            if let Some(Ipld::Link(cid)) = ref_map.get("$link") {
331	                                out.push(*cid);
332	                            }
333	                        }
334	                        _ => {}
335	                    }
336	                }
337	            }
338	            // Recurse into all map values — a blob could be nested inside an embed.
339	            for v in map.values() {
340	                collect_blob_cids(v, out);
341	            }
342	        }
343	        Ipld::List(items) => {
344	            for v in items {
345	                collect_blob_cids(v, out);
346	            }
347	        }
348	        // Scalars and links are leaves — no further recursion.
349	        _ => {}
350	    }
351	}
352	
353	/// Write a record provided as JSON, converting it to the ATProto data model first.
354	/// Returns the record block CID. Errors with `InvalidRecord` for floats or malformed
355	/// `$link`/`$bytes`.
356	pub async fn put_record_json<S>(
357	    repo: &mut Repository<S>,
358	    signer: &CommitSigner,
359	    key: &str,
360	    json: &serde_json::Value,
361	) -> Result<Cid, RecordError>
362	where
363	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
364	{
365	    let value = json_to_record_value(json)?;
366	    put_record(repo, signer, key, &value).await
367	}
368	
369	/// Read a record and return it as JSON, mapping the ATProto data model back to its JSON
370	/// form (CID links → `{"$link": ...}`, byte strings → `{"$bytes": ...}`).
371	pub async fn get_record_json<S>(
372	    repo: &mut Repository<S>,
373	    key: &str,
374	) -> Result<Option<serde_json::Value>, RecordError>
375	where
376	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
377	{
378	    let value: Option<Ipld> = get_record(repo, key).await?;
379	    value.map(|v| record_value_to_json(&v)).transpose()
380	}
381	
382	/// A single record returned by [`list_records_json`].
383	pub struct ListedRecord {
384	    /// The record key (the MST key with the `<collection>/` prefix stripped).
385	    pub rkey: String,
386	    /// The CID of the record block.
387	    pub cid: Cid,
388	    /// The record value as JSON (CID links → `{"$link": ...}`, bytes → `{"$bytes": ...}`).
389	    pub value: serde_json::Value,
390	}
391	
392	/// A page of records from [`list_records_json`].
393	pub struct ListRecordsPage {
394	    /// The records in this page, in traversal order.
395	    pub records: Vec<ListedRecord>,
396	    /// The cursor to pass to fetch the next page, or `None` when the listing is exhausted.
397	    pub cursor: Option<String>,
398	}
399	
400	/// List records in a collection, in MST (lexicographic by rkey) order, with cursor pagination.
401	///
402	/// - `limit` caps the number of records returned (the caller is responsible for clamping it
403	///   to any policy bounds).
404	/// - `cursor`, when present, is an rkey from a previous page; only records *after* it in the
405	///   current traversal direction are returned.
406	/// - `reverse` walks the collection in descending rkey order instead of ascending.
407	///
408	/// The returned `cursor` is the last rkey of the page, set only when more records remain.
409	pub async fn list_records_json<S>(
410	    repo: &mut Repository<S>,
411	    collection: &str,
412	    limit: usize,
413	    cursor: Option<&str>,
414	    reverse: bool,
415	) -> Result<ListRecordsPage, RecordError>
416	where
417	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
418	{
419	    use futures::StreamExt;
420	
421	    // The MST key for a record is `<collection>/<rkey>`; the trailing slash confines the
422	    // prefix scan to this exact collection (so `app.bsky.feed.post` won't match
423	    // `app.bsky.feed.postx`).
424	    let prefix = format!("{collection}/");
425	    let strip = |key: &str| key.strip_prefix(&prefix).unwrap_or(key).to_string();
426	
427	    // Collect up to `limit + 1` post-cursor entries — the extra one tells us whether more
428	    // records remain (and thus whether to emit a cursor) without reading the whole page.
429	    let want = limit.saturating_add(1);
430	    let mut entries: Vec<(String, Cid)> = Vec::new();
431	    {
432	        let mut tree = repo.tree();
433	        let mut stream = Box::pin(tree.entries_prefixed(&prefix));
434	
435	        if reverse {
436	            // `entries_prefixed` only yields ascending order and atrium-repo exposes no
437	            // reverse traversal, so descending order requires materializing the collection
438	            // and walking it backwards. Cursor/limit are then applied while walking.
439	            let mut all: Vec<(String, Cid)> = Vec::new();
440	            while let Some(res) = stream.next().await {
441	                let (key, cid) =
442	                    res.map_err(|e| RecordError::Repo(format!("list entries: {e}")))?;
443	                all.push((strip(&key), cid));
444	            }
445	            for (rkey, cid) in all.into_iter().rev() {
446	                if cursor.is_some_and(|c| rkey.as_str() >= c) {
447	                    continue;
448	                }
449	                entries.push((rkey, cid));
450	                if entries.len() == want {
451	                    break;
452	                }
453	            }
454	        } else {
455	            // Ascending: skip up to and including the cursor, then take `limit + 1` and stop.
456	            // Memory and block reads stay proportional to the page, not the collection.
457	            while let Some(res) = stream.next().await {
458	                let (key, cid) =
459	                    res.map_err(|e| RecordError::Repo(format!("list entries: {e}")))?;
460	                let rkey = strip(&key);
461	                if cursor.is_some_and(|c| rkey.as_str() <= c) {
462	                    continue;
463	                }
464	                entries.push((rkey, cid));
465	                if entries.len() == want {
466	                    break;
467	                }
468	            }
469	        }
470	    }
471	
472	    // The (limit + 1)-th entry, if present, means more records remain past this page.
473	    let has_more = entries.len() > limit;
474	    entries.truncate(limit);
475	
476	    // Resolve each record's value by its MST key. `get_raw_cid` would re-enumerate the
477	    // entire MST per record (atrium walks every entry to prove the CID belongs to the
478	    // repo), making a page O(limit × repo-size) — pathological on a mature repo. We
479	    // already walked the tree to collect `(rkey, cid)`, so a keyed lookup (`get_raw`,
480	    // one tree descent) is both membership-safe and O(log n) per record.
481	    let mut records = Vec::with_capacity(entries.len());
482	    for (rkey, cid) in entries {
483	        let full_key = format!("{prefix}{rkey}");
484	        let value: Option<Ipld> = repo
485	            .get_raw(&full_key)
486	            .await
487	            .map_err(|e| RecordError::Repo(format!("read record block: {e}")))?;
488	        let value = value.ok_or(RecordError::NotFound)?;
489	        records.push(ListedRecord {
490	            rkey,
491	            cid,
492	            value: record_value_to_json(&value)?,
493	        });
494	    }
495	
496	    let cursor = if has_more {
497	        records.last().map(|r| r.rkey.clone())
498	    } else {
499	        None
500	    };
501	
502	    Ok(ListRecordsPage { records, cursor })
503	}
504	
505	/// List the distinct collection NSIDs present in a repository, in lexicographic order.
506	///
507	/// Walks every MST key (`<collection>/<rkey>`) and collects the unique `<collection>`
508	/// prefixes. An empty repo (genesis, no records) yields an empty list. Used by
509	/// `com.atproto.repo.describeRepo` to report which collections a repo holds.
510	pub async fn list_collections<S>(repo: &mut Repository<S>) -> Result<Vec<String>, RecordError>
511	where
512	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
513	{
514	    use futures::StreamExt;
515	
516	    // MST keys arrive in lexicographic order, and every key for a collection shares the
517	    // `<collection>/` prefix — so any key sorting between two of a collection's keys must
518	    // also carry that prefix. Equal-collection keys are therefore contiguous, and a single
519	    // last-seen comparison dedupes them in O(n) with no intermediate set.
520	    let mut collections: Vec<String> = Vec::new();
521	    let mut tree = repo.tree();
522	    let mut stream = Box::pin(tree.keys());
523	    while let Some(res) = stream.next().await {
524	        let key = res.map_err(|e| RecordError::Repo(format!("list keys: {e}")))?;
525	        // MST keys are `<collection>/<rkey>`; the collection is everything before the
526	        // first slash. Keys without a slash are not valid records and are skipped.
527	        if let Some((collection, _)) = key.split_once('/') {
528	            if collections.last().map(String::as_str) != Some(collection) {
529	                collections.push(collection.to_string());
530	            }
531	        }
532	    }
533	    Ok(collections)
534	}
