560	/// Validate that `collection` is a syntactically valid NSID, matching the ATProto
561	/// reference grammar (`@atproto/syntax`'s `ensureValidNsid`) so a collection accepted
562	/// here is also accepted by relays and AppViews — a collection that passes local
563	/// validation but fails theirs produces records that write locally yet are silently
564	/// rejected downstream, a confusing one-way sync.
565	///
566	/// - total length 1..=317, at least three dot-separated segments, no slashes;
567	/// - every segment is 1..=63 chars of `[A-Za-z0-9-]` and neither starts nor ends with a hyphen;
568	/// - the first (authority) segment does not start with a digit;
569	/// - the final (name) segment is a letter followed by letters/digits only (no hyphens).
570	///
571	/// The digit restriction is deliberately only on the *first* segment (not every authority
572	/// segment) to mirror the reference implementation exactly — being stricter would reject
573	/// collections the network accepts, the opposite one-way divergence.
574	pub fn validate_collection(collection: &str) -> Result<(), RecordError> {
575	    let invalid =
576	        || RecordError::InvalidPath(format!("collection is not a valid NSID: {collection}"));
577	
578	    if collection.is_empty() || collection.len() > 317 {
579	        return Err(invalid());
580	    }
581	    let segments: Vec<&str> = collection.split('.').collect();
582	    if segments.len() < 3 {
583	        return Err(invalid());
584	    }
585	    let last = segments.len() - 1;
586	    for (i, seg) in segments.iter().enumerate() {
587	        let bytes = seg.as_bytes();
588	        if seg.is_empty() || seg.len() > 63 {
589	            return Err(invalid());
590	        }
591	        if !seg.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
592	            return Err(invalid());
593	        }
594	        if bytes[0] == b'-' || bytes[bytes.len() - 1] == b'-' {
595	            return Err(invalid());
596	        }
597	        if i == 0 && bytes[0].is_ascii_digit() {
598	            return Err(invalid());
599	        }
600	        // Final (name) segment: a letter followed by letters/digits only (no hyphens).
601	        if i == last && (!bytes[0].is_ascii_alphabetic() || seg.chars().any(|c| c == '-')) {
602	            return Err(invalid());
603	        }
604	    }
605	    Ok(())
606	}
