695	/// Return the CID of the record block currently stored at `key`, or `None` if absent.
696	///
697	/// The MST maps each record key directly to its block CID, so this is a single tree
698	/// lookup with no record-block fetch. Used to enforce the `swapRecord`
699	/// optimistic-concurrency precondition without deserializing the record itself.
700	pub async fn get_record_cid<S>(
701	    repo: &mut Repository<S>,
702	    key: &str,
703	) -> Result<Option<Cid>, RecordError>
704	where
705	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
706	{
707	    repo.tree()
708	        .get(key)
709	        .await
710	        .map_err(|e| RecordError::Repo(format!("get record cid: {e}")))
711	}
