735	/// Delete a record from the repository.
736	///
737	/// Returns `Ok(())` if the record was deleted, or `Err(RecordError::NotFound)` if it doesn't exist.
738	/// The commit is signed with the provided signer.
739	///
740	/// # Usage
741	///
742	/// ```rust,ignore
743	/// use repo_engine::delete_record;
744	///
745	/// let mut repo = Repository::open(&mut block_store, root_cid).await?;
746	/// delete_record(&mut repo, &signer, "app.bsky.feed.post/abc123").await?;
747	/// ```
748	pub async fn delete_record<S>(
749	    repo: &mut Repository<S>,
750	    signer: &CommitSigner,
751	    key: &str,
752	) -> Result<(), RecordError>
753	where
754	    S: atrium_repo::blockstore::AsyncBlockStoreRead + atrium_repo::blockstore::AsyncBlockStoreWrite,
755	{
756	    // Capture the previous commit's rev before the builder borrows the repo mutably.
757	    let prev_rev = repo.commit().rev();
758	    let mut builder = repo
759	        .delete_raw(key)
760	        .await
761	        .map_err(|e| RecordError::Repo(format!("delete record: {e}")))?;
762	    // Force a strictly-increasing rev (atrium defaults it to the raw wall clock).
763	    builder.rev(next_commit_rev(prev_rev.as_ref())?);
764	
765	    let sig = signer.sign(&builder.bytes());
766	    builder
767	        .finalize(sig)
768	        .await
769	        .map_err(|e| RecordError::Repo(format!("finalize commit: {e}")))?;
770	
771	    Ok(())
772	}
