        for nsid in valid {
            assert!(
                validate_collection(nsid).is_ok(),
                "expected valid NSID from interop fixture: {nsid:?}",
            );
        }
        for nsid in invalid {
            assert!(
                validate_collection(nsid).is_err(),
                "expected invalid NSID from interop fixture: {nsid:?}",
            );
        }
    }

